<script setup>
import { onMounted, onBeforeUnmount, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { apiClient, currentApiCacheScope } from '../../utils/api.js';
import { shanghaiDateTimeText } from '../../utils/shanghai-date.js';
import WbListingEditor from '../../components/listing/WbListingEditor.vue';
import MarketplaceBadge from '../../components/MarketplaceBadge.vue';
const shops=ref([]),shopId=ref(null),templates=ref([]),drafts=ref([]),active=ref('templates'),busy=ref(false),notice=ref('');
const defaultValues=reactive({});
function openTemplate(row){for(const key of Object.keys(defaultValues))delete defaultValues[key];for(const item of row.defaults?.characteristics||[])defaultValues[item.id]=Array.isArray(item.value)?item.value.join(', '):item.value;preview.value={template:row};}
async function saveDefaults(){await run(async scope=>{const t=preview.value.template;const characteristics=t.attributes.map(a=>({id:a.charcID,value:Number(a.charcType)===4?(defaultValues[a.charcID]===null||defaultValues[a.charcID]===undefined||defaultValues[a.charcID]===''?undefined:Number(defaultValues[a.charcID])):String(defaultValues[a.charcID]||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean)})).filter(a=>a.value!==undefined&&(!Array.isArray(a.value)||a.value.length));const r=await apiClient.post('/api/wb/listing-templates/save',{shop_id:shopId.value,template_id:t.id,revision:t.revision,name:t.name,subject_id:t.subject_id,defaults:{currency:'CNY',characteristics}});if(scope!==currentApiCacheScope())return;preview.value={template:r.template};await load();ElMessage.success('模板默认属性已保存，已有商品草稿不会被覆盖');});}
const importer=reactive({visible:false,name:'',search:'',categories:[],subject:null}),editor=reactive({visible:false,draft:null}),preview=ref(null),checks=ref([]);
const time=value=>shanghaiDateTimeText(value,{assumeUtcWhenNaive:true});
async function run(work){if(busy.value)return;const scope=currentApiCacheScope();busy.value=true;try{await work(scope);}catch(e){if(scope===currentApiCacheScope())ElMessage.error(e.message);}finally{busy.value=false;}}
async function load(){const scope=currentApiCacheScope(),target=Number(shopId.value);templates.value=[];drafts.value=[];if(!target)return;const [t,d]=await Promise.all([apiClient.get(`/api/wb/listing-templates?shop_id=${target}`,{noCache:true}),apiClient.get(`/api/wb/listing-drafts?shop_id=${target}`,{noCache:true})]);if(scope===currentApiCacheScope()&&target===Number(shopId.value)){templates.value=t.rows;drafts.value=d.rows;}}
async function bootstrap(){await run(async scope=>{const s=await apiClient.get('/api/wb/shops',{noCache:true});if(scope!==currentApiCacheScope())return;shops.value=s.filter(s=>s.status==='active');shopId.value=shops.value[0]?.id||null;await load();});}
async function findCategories(){await run(async scope=>{const r=await apiClient.get(`/api/wb/categories?shop_id=${shopId.value}&search=${encodeURIComponent(importer.search)}`);if(scope===currentApiCacheScope())importer.categories=r.data||[];});}
async function importTemplate(){await run(async scope=>{await apiClient.post('/api/wb/listing-templates/save',{shop_id:shopId.value,name:importer.name,subject_id:importer.subject,defaults:{currency:'CNY',characteristics:[]}});if(scope!==currentApiCacheScope())return;importer.visible=false;await load();ElMessage.success('WB 类目模板已导入');});}
async function validate(row){checks.value=[];await run(async scope=>{const r=await apiClient.post('/api/wb/listing-drafts/validate',{shop_id:shopId.value,draft_id:row.id});if(scope!==currentApiCacheScope())return;checks.value=r.errors||[];notice.value=r.ok?'资料校验通过，草稿仍未提交到 WB。':'以下资料需要在商品草稿中补全。';preview.value=row;});}
function openEditor(draft=null){if(!templates.value.length)return ElMessage.warning('请先导入 WB 类目模板');Object.assign(editor,{visible:true,draft});}
function reset(){shops.value=[];shopId.value=null;templates.value=[];drafts.value=[];preview.value=null;editor.visible=false;importer.visible=false;bootstrap();}
onMounted(()=>{bootstrap();window.addEventListener('erp:auth-scope-changed',reset);});onBeforeUnmount(()=>window.removeEventListener('erp:auth-scope-changed',reset));
</script>
<template>
  <div class="wb-review-page">
    <div class="page-heading"><h2><MarketplaceBadge platform="wb"/> WB 商品上架</h2><div><el-button :disabled="!shopId||busy" @click="Object.assign(importer,{visible:true,name:'',search:'',categories:[],subject:null})">导入类目模板</el-button><el-button type="primary" :disabled="!shopId||busy||!templates.length" @click="openEditor()">创建商品草稿</el-button></div></div>
    <el-alert title="先导入 WB 类目模板，再套用商品资料、填写属性和价格。当前仅保存和预览，尚未开放提交上架。" type="info" :closable="false"/>
    <el-select v-model="shopId" :disabled="busy" placeholder="选择 WB 店铺" @change="load"><el-option v-for="shop in shops" :key="shop.id" :value="Number(shop.id)" :label="shop.name"/></el-select>
    <el-tabs v-model="active"><el-tab-pane label="类目模板" name="templates"/><el-tab-pane label="商品草稿" name="drafts"/></el-tabs>
    <el-table v-if="active==='templates'" :data="templates" v-loading="busy" stripe border empty-text="暂无 WB 模板，请先导入类目模板"><el-table-column prop="name" label="模板名称" min-width="200"/><el-table-column prop="category_name" label="WB 类目" min-width="200"/><el-table-column label="类目属性" width="180"><template #default="{row}">{{row.attributes.length}} 项 · {{row.attributes.filter(a=>a.required).length}} 项必填</template></el-table-column><el-table-column label="币种" width="120"><template #default>人民币 CNY</template></el-table-column><el-table-column label="操作" width="200"><template #default="{row}"><el-button link type="primary" @click="openTemplate(row)">查看模板</el-button><el-button link type="primary" @click="openEditor({payload:{template_id:Number(row.id),subject_id:Number(row.subject_id),currency:'CNY',images:[],card:{vendorCode:'',title:'',brand:'',description:'',dimensions:{length:null,width:null,height:null,weightBrutto:null},sizes:[{techSize:'0',price:null,skus:[]}],characteristics:[]}}})">套用模板</el-button></template></el-table-column></el-table>
    <el-table v-else :data="drafts" v-loading="busy" stripe border empty-text="暂无 WB 商品草稿"><el-table-column label="商品" min-width="300"><template #default="{row}"><div class="wb-product"><el-image v-if="row.payload.images?.length" class="wb-thumb" :src="row.payload.images[0]" :preview-src-list="row.payload.images" preview-teleported fit="cover"/><div v-else class="wb-thumb">无图</div><div><strong>{{row.payload.card.title}}</strong><p>{{row.vendor_code}}</p><small>{{row.payload.template_name}}</small></div></div></template></el-table-column><el-table-column label="售价" width="150"><template #default="{row}">¥ {{row.payload.card.sizes[0]?.price??'待填写'}} CNY</template></el-table-column><el-table-column label="状态" width="130"><template #default><el-tag type="info">待审核 · 未提交</el-tag></template></el-table-column><el-table-column label="更新时间（北京）" width="175"><template #default="{row}">{{time(row.updated_at)}}</template></el-table-column><el-table-column label="操作" width="240"><template #default="{row}"><el-button link type="primary" @click="openEditor(row)">编辑</el-button><el-button link type="primary" @click="preview=row;checks=[]">预览</el-button><el-button link type="primary" :disabled="busy" @click="validate(row)">校验资料</el-button></template></el-table-column></el-table>
    <WbListingEditor v-if="editor.visible" :shop-id="Number(shopId)" :templates="templates" :draft="editor.draft" @close="editor.visible=false" @saved="load"/>
    <el-dialog v-model="importer.visible" title="导入 WB 类目模板" width="min(760px,95vw)" destroy-on-close><el-form label-position="top"><el-form-item label="模板名称" required><el-input v-model="importer.name" placeholder="例如：WB 汽车钥匙套"/></el-form-item><el-form-item label="搜索 WB 类目"><div class="inline"><el-input v-model="importer.search" placeholder="输入中文或俄文类目关键词" @keyup.enter="findCategories"/><el-button :loading="busy" @click="findCategories">搜索</el-button></div></el-form-item><el-form-item label="选择类目" required><el-select v-model="importer.subject" filterable><el-option v-for="c in importer.categories" :key="c.subjectID" :value="c.subjectID" :label="c.parentName+' / '+c.subjectName"/></el-select></el-form-item></el-form><template #footer><el-button @click="importer.visible=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!importer.subject||!importer.name" @click="importTemplate">导入模板及属性</el-button></template></el-dialog>
    <el-drawer v-if="preview" :model-value="true" :title="preview.template?'WB 类目模板':'WB 商品草稿预览'" size="min(900px,95vw)" @close="preview=null">
      <template v-if="preview.template"><h3>{{preview.template.name}}</h3><p>{{preview.template.category_name}} · 类目 {{preview.template.subject_id}}</p><el-table :data="preview.template.attributes" border><el-table-column prop="name" label="属性"/><el-table-column label="必填" width="90"><template #default="{row}">{{row.required?'是':'否'}}</template></el-table-column><el-table-column label="填写方式"><template #default="{row}"><el-input-number v-if="Number(row.charcType)===4" v-model="defaultValues[row.charcID]"/><el-input v-else v-model="defaultValues[row.charcID]" placeholder="模板默认值（可留空）"/></template></el-table-column></el-table><el-button type="primary" :loading="busy" @click="saveDefaults">保存模板默认属性</el-button></template>
      <template v-else><el-alert title="待你审核，未向 WB 提交" type="info" :closable="false"/><el-alert v-for="note in preview.payload.review_notes||[]" :key="note" :title="note" type="warning" :closable="false"/><h3>{{preview.payload.card.title}}</h3><p>货号：{{preview.vendor_code}}　售价：¥ {{preview.payload.card.sizes[0]?.price??'待填写'}} CNY</p><p>模板：{{preview.payload.template_name}}</p><p class="description">{{preview.payload.card.description}}</p><p>包装：{{preview.payload.card.dimensions.length}} × {{preview.payload.card.dimensions.width}} × {{preview.payload.card.dimensions.height}} cm；{{preview.payload.card.dimensions.weightBrutto}} kg</p><div class="preview-images"><el-image v-for="(image,index) in preview.payload.images" :key="index" :src="image" :preview-src-list="preview.payload.images" :initial-index="index" preview-teleported fit="contain"/></div><el-table :data="preview.payload.card.characteristics" border><el-table-column label="属性"><template #default="{row}">{{preview.payload.attributes_schema?.find(a=>Number(a.charcID)===Number(row.id))?.name||row.id}}</template></el-table-column><el-table-column label="所填值"><template #default="{row}">{{Array.isArray(row.value)?row.value.join('、'):row.value}}</template></el-table-column></el-table><el-alert v-if="notice" :title="notice" type="info" :closable="false"/><el-alert v-for="error in checks" :key="error" :title="error" type="warning" :closable="false"/></template>
    </el-drawer>
  </div>
</template>
<style scoped>
.wb-review-page{display:grid;gap:16px;min-width:0}.page-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.page-heading h2{margin:0}.wb-review-page>.el-select{width:300px}.wb-product{display:flex;gap:12px;align-items:center;min-height:92px}.wb-thumb{width:64px;height:84px;flex-shrink:0;background:var(--el-fill-color-light);border-radius:var(--el-border-radius-base)}.inline{display:flex;gap:12px;width:100%}.preview-images{display:flex;flex-wrap:wrap;gap:12px;margin:16px 0}.preview-images .el-image{width:160px;height:210px}.description{white-space:pre-wrap;line-height:1.7}
</style>
